CREATE TABLE public.households (user_id uuid PRIMARY KEY, name text NOT NULL DEFAULT 'My family', children integer NOT NULL DEFAULT 0 CHECK(children BETWEEN 0 AND 20), adults integer NOT NULL DEFAULT 1 CHECK(adults BETWEEN 1 AND 20), seniors integer NOT NULL DEFAULT 0 CHECK(seniors BETWEEN 0 AND 20), commute text NOT NULL DEFAULT 'metro', exercise text NOT NULL DEFAULT 'walking', checklist jsonb NOT NULL DEFAULT '{}', trips jsonb NOT NULL DEFAULT '[]', messages jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.households TO authenticated; GRANT ALL ON public.households TO service_role; ALTER TABLE public.households ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own household" ON public.households FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);